    c_bounds = [-1] + cs + [w]
    row_spans = [(r_bounds[i] + 1, r_bounds[i + 1]) for i in range(len(r_bounds)-1)]
    col_spans = [(c_bounds[i] + 1, c_bounds[i + 1]) for i in range(len(c_bounds)-1)]

    seeds = {}
    for ri, (r0, r1) in enumerate(row_spans):
        for ci, (c0, c1) in enumerate(col_spans):
            vals = {g[r][c] for r in range(r0, r1) for c in range(c0, c1) if g[r][c] not in (0, 8)}
