                seeds[(ri, ci)] = next(iter(vals))

    row_colors, col_colors = {}, {}
    for color in set(seeds.values()):
        locs = [(ri, ci) for (ri, ci), v in seeds.items() if v == color]
        for ri in set(r for r, _ in locs):
            if sum(1 for r, _ in locs if r == ri) >= 2:
                row_colors[ri] = color
        for ci in set(c for _, c in locs):
            if sum(1 for _, c in locs if c == ci) >= 2:
                col_colors[ci] = color

    for ri, (r0, r1) in enumerate(row_spans):
        for ci, (c0, c1) in enumerate(col_spans):
            colors = set()
            if ri in row_colors:
                colors.add(row_colors[ri])
            if ci in col_colors:
                colors.add(col_colors[ci])
            if not colors:
                continue
            value = next(iter(colors)) if len(colors) == 1 else 6
            for r in range(r0, r1):
                for c in range(c0, c1):
                    g[r][c] = value
    return g
